import { describe, expect, test } from "bun:test";

import { toPlainMarkdown } from "../src/lib/llms-render";

const md = (...lines: string[]) => lines.join("\n");

describe("toPlainMarkdown", () => {
  test("drops MDX imports, exports, and comments", () => {
    expect(
      toPlainMarkdown(
        md(
          'import Journey from "@/components/blog/Journey.astro";',
          "export const meta = { draft: false };",
          "{/* generated by docs-factory */}",
          "Body text.",
        ),
      ),
    ).toBe("Body text.");
  });

  test("flattens callouts to bold labels", () => {
    expect(
      toPlainMarkdown(
        md(
          ":::tip[Heads up]",
          "Use the CLI.",
          ":::",
          "::::warning",
          "Careful.",
          "::::",
          ":::aside",
          "Custom.",
          ":::",
        ),
      ),
    ).toBe(
      md(
        "**Tip**",
        "Use the CLI.",
        "**Warning**",
        "Careful.",
        "**aside**",
        "Custom.",
      ),
    );
  });

  test("turns Journey steps into headings and drops diagram components", () => {
    expect(
      toPlainMarkdown(
        md(
          "<Journey>",
          '<JourneyStep step="Create a catalog">',
          "Run the command.",
          "</JourneyStep>",
          "</Journey>",
          '<LikeC4View viewId="index" />',
          '<TrestleView src="./env.json" />',
        ),
      ),
    ).toBe(md("### Create a catalog", "Run the command."));
  });

  test("replaces local images with their alt text and keeps remote ones", () => {
    expect(
      toPlainMarkdown(
        "See ![the diagram](./diagram.png), ![](./spacer.png) and ![logo](https://unitycatalog.io/logo.png).",
      ),
    ).toBe(
      "See [Image: the diagram],  and ![logo](https://unitycatalog.io/logo.png).",
    );
  });

  test("unescapes directive colons", () => {
    expect(toPlainMarkdown("Step 1\\: install")).toBe("Step 1: install");
  });

  test("leaves fenced code untouched", () => {
    const fenced = md(
      "```ts",
      'import { x } from "y";',
      ":::note",
      "![alt](./img.png)",
      "```",
      "~~~",
      "<Journey>",
      "~~~",
    );
    expect(toPlainMarkdown(fenced)).toBe(fenced);
  });

  test("collapses runs of blank lines and trims", () => {
    expect(toPlainMarkdown(md("", "One.", "", "", "", "Two.", "", ""))).toBe(
      md("One.", "", "Two."),
    );
  });
});
